import Locale, { LocaleOptions } from "./locale";
import * as util from "./util";
import cookie from "./cookie";

const DEFAULT_KEY = "x-hng";

const DEFAULT_OPTIONS: LocaleOptions  = {
  key: DEFAULT_KEY,
  maxAge: 6 * 30 * 24 * 60 * 60,
  path: "/"
};

/**
 * Create an instance of Axios
 * @param {LocaleOptions} options default config for the instance
 * @return {Locale} A new instance of Locale
 */
export function createInstance(options?: LocaleOptions): Locale {
  options = Object.assign({}, DEFAULT_OPTIONS , options);
  const instance = new Locale(options);
  return instance;
}

const locale = createInstance();

const exportObject = {
  locale,
  cookie,
  util,
  create: createInstance,
  getKey: locale.getKey.bind(locale),
  getLocale: locale.getLocale.bind(locale),
  getLocaleString: locale.getLocaleString.bind(locale),
  getEnv: locale.getEnv.bind(locale),
  setLocale: locale.setLocale.bind(locale),
  setRegion: locale.setRegion.bind(locale),
  setLang: locale.setLang.bind(locale),
  setCurrency: locale.setCurrency.bind(locale),
  setTimeZone: locale.setTimeZone.bind(locale),
  setLocaleWithObject: locale.setLocaleWithObject.bind(locale),
  clear: locale.clear.bind(locale),
}

export default exportObject;

module.exports = exportObject;

export const sdkVersion = "1.0.3";